define("local_gerenciamentomatriculas/course_code_repository",["core/ajax"],function(Ajax){"use strict";var failureEvent="local_gerenciamentomatriculas:courseautocompletefailed";return{transport:function(selector,query,success){var normalizedQuery=query.trim();if(normalizedQuery.length<2){success([]);return}Ajax.call([{methodname:"local_gerenciamentomatriculas_search_course_codes",args:{query:normalizedQuery}}])[0].then(success).catch(function(){document.dispatchEvent(new CustomEvent(failureEvent,{detail:{selector:selector}}));success([])})},processResults:function(selector,results){return Array.isArray(results)?results:[]}}});
